//! Finite connected components generated by certified adjacent interchanges.
//! This is a state-dependent trace quotient at a fixed start, not an assumed
//! context-free trace monoid. Complete enumeration or typed resource refusal.
use crate::finite_continuation::{ContinuationError, PartialDynamics};
use crate::finite_independence::{SwapCertificate, SwapOutcome};
use std::collections::{BTreeSet, VecDeque};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReplayMode {
    ExactState,
    ProtectedFutures,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TraceLimits {
    pub max_words: usize,
    pub max_word_len: usize,
    pub max_swap_checks: usize,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TraceLink {
    pub from: Vec<usize>,
    pub position: usize,
    pub swap: SwapCertificate,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TraceComponent {
    pub start: usize,
    pub word: Vec<usize>,
    pub mode: ReplayMode,
    /// Sorted complete component; first entry is its canonical representative.
    pub members: Vec<Vec<usize>>,
    /// Discovery tree, retaining the actual witnesses that generate the class.
    pub tree: Vec<TraceLink>,
}
impl PartialDynamics {
    pub fn trace_component(
        &self,
        start: usize,
        word: &[usize],
        mode: ReplayMode,
        limits: TraceLimits,
    ) -> Result<TraceComponent, ContinuationError> {
        if word.len() > limits.max_word_len || limits.max_words == 0 {
            return Err(ContinuationError::WorkLimit);
        }
        if self.run(start, word)?.is_none() {
            return Err(ContinuationError::CertificateMismatch);
        }
        let pairs = self
            .reports()
            .len()
            .checked_add(1)
            .and_then(|n| n.checked_mul(n))
            .ok_or(ContinuationError::WorkLimit)?;
        let mut seen = BTreeSet::from([word.to_vec()]);
        let mut queue = VecDeque::from([word.to_vec()]);
        let mut tree = Vec::new();
        let mut checks = 0usize;
        while let Some(w) = queue.pop_front() {
            for i in 0..w.len().saturating_sub(1) {
                if checks >= limits.max_swap_checks {
                    return Err(ContinuationError::WorkLimit);
                }
                checks += 1;
                let s = self
                    .run(start, &w[..i])?
                    .ok_or(ContinuationError::CertificateMismatch)?;
                let swap = self.certify_swap(s, w[i], w[i + 1], pairs)?;
                let SwapOutcome::Independent { ab, ba } = swap.outcome else {
                    continue;
                };
                if mode == ReplayMode::ExactState && ab != ba {
                    continue;
                }
                let mut next = w.clone();
                next.swap(i, i + 1);
                if !seen.contains(&next) {
                    if seen.len() >= limits.max_words {
                        return Err(ContinuationError::WorkLimit);
                    }
                    seen.insert(next.clone());
                    queue.push_back(next);
                    tree.push(TraceLink {
                        from: w.clone(),
                        position: i,
                        swap,
                    });
                }
            }
        }
        Ok(TraceComponent {
            start,
            word: word.to_vec(),
            mode,
            members: seen.into_iter().collect(),
            tree,
        })
    }
    /// Recompute closure, not just the submitted edges. Removing a member or
    /// substituting another start/mode/word cannot certify an incomplete class.
    pub fn verify_trace(
        &self,
        start: usize,
        word: &[usize],
        mode: ReplayMode,
        limits: TraceLimits,
        certificate: &TraceComponent,
    ) -> Result<(), ContinuationError> {
        if self.trace_component(start, word, mode, limits)? == *certificate {
            Ok(())
        } else {
            Err(ContinuationError::CertificateMismatch)
        }
    }
}
